{\"n\":26,\"src\":\"THALABI\",\"g\":\"core\",\"c\":[\"2c\",\"2d\",\"4d\",\"5d\"],\"why\":\"Identifies al-ʿaṣr as the day's final hour.\"}
{\"n\":27,\"src\":\"THALABI\",\"g\":\"core\",\"c\":[\"2c\",\"2d\"],\"why\":\"Identifies the oath-object as the Asr prayer, a rival referent.\"}
