{\"n\":30,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"2c\",\"2d\",\"3b\"],\"why\":\"Ibn Abbas and Zayd identify al-ʿaṣr as dahr, the age or time.\"}
{\"n\":31,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"2c\",\"2d\",\"4d\",\"5d\"],\"why\":\"Hasan and Qatada identify al-ʿaṣr as the afternoon interval to sunset.\"}
{\"n\":32,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"2c\",\"2d\",\"3b\"],\"why\":\"Offers the Prophet's era as a specific temporal referent for al-ʿaṣr.\"}
{\"n\":33,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"2c\",\"2d\"],\"why\":\"Muqatil identifies the oath-object as the afternoon prayer.\"}
{\"n\":34,\"src\":\"MAWARDI-FULL\",\"g\":\"core\",\"c\":[\"2c\",\"2d\",\"4d\",\"5d\"],\"why\":\"Connects al-ʿaṣr with the day's closing acts and end point.\"}
{\"n\":35,\"src\":\"MAWARDI-FULL\",\"g\":\"off\",\"why\":\"The sura's Meccan or Medinan classification is not a page claim.\"}
EOF
